import { useCallback, useRef, useState } from "react";
import { createError, ensureError, toError } from "../../errors/veryfront-error.js";
import { csrfMutationHeaders } from "../../security/csrf/browser-mutation-headers.js";
/** React hook for agent. */
export function useAgent(options) {
    const [messages, setMessages] = useState([]);
    const [toolCalls, setToolCalls] = useState([]);
    const [status, setStatus] = useState("idle");
    const [thinking, setThinking] = useState();
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const abortControllerRef = useRef(null);
    const invoke = useCallback(async (input) => {
        setIsLoading(true);
        setError(null);
        setStatus("thinking");
        setToolCalls([]);
        const abortController = new AbortController();
        abortControllerRef.current = abortController;
        try {
            const endpoint = `/api/agents/${options.agent}`;
            const response = await fetch(endpoint, {
                method: "POST",
                // CSRF is enforced in every environment, local development included,
                // so this POST has to echo the configured CSRF cookie the document
                // response issued or the server answers 403.
                headers: csrfMutationHeaders(endpoint, {
                    headers: { "Content-Type": "application/json" },
                }),
                body: JSON.stringify({ input, messages }),
                signal: abortController.signal,
            });
            if (!response.ok) {
                throw toError(createError({
                    type: "agent",
                    message: `Agent error: ${response.status}`,
                }));
            }
            const data = (await response.json());
            const nextMessages = data.messages ?? [];
            const nextToolCalls = data.toolCalls ?? [];
            const nextStatus = data.status ?? "completed";
            setMessages(nextMessages);
            setToolCalls(nextToolCalls);
            setStatus(nextStatus);
            setThinking(data.thinking);
            for (const tc of nextToolCalls) {
                options.onToolCall?.(tc);
                if (tc.result)
                    options.onToolResult?.(tc, tc.result);
            }
        }
        catch (err) {
            if (err instanceof Error && err.name === "AbortError")
                return;
            const nextError = ensureError(err);
            setError(nextError);
            setStatus("error");
            options.onError?.(nextError);
        }
        finally {
            setIsLoading(false);
            abortControllerRef.current = null;
        }
    }, [messages, options]);
    const stop = useCallback(() => {
        abortControllerRef.current?.abort();
        abortControllerRef.current = null;
        setIsLoading(false);
        setStatus("idle");
    }, []);
    return {
        messages,
        toolCalls,
        status,
        thinking,
        invoke,
        stop,
        isLoading,
        error,
    };
}
